package com.bananalab.lite;
import java.util.*;import java.util.regex.*;import org.json.*;
/** Explicit bounded Java method statements, not an arbitrary Java interpreter. */
final class JavaTextPlan{
 static final String LIT="\"(?:[^\"\\\\\\r\\n]|\\\\[\"\\\\nrt])*\"";
 static final class Rule{String variable,operation,trigger,reply;Rule(String v,String o,String t,String r){variable=v;operation=o;trigger=t;reply=r;}}
 final List<Rule> rules=new ArrayList<>();boolean replace=false;
 static String literal(String value){if(value.length()>400)throw new IllegalArgumentException("El texto admite hasta400 caracteres.");return "\""+value.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
 static String decode(String raw)throws Exception{return new JSONArray("["+raw+"]").getString(0);}
 static void check(Rule r){if(!r.variable.matches("message|text")||!r.operation.matches("equals|startsWith|endsWith|contains")||r.trigger.trim().length()<2||r.trigger.length()>120||r.reply.trim().isEmpty()||r.reply.length()>400||r.trigger.contains("\\u")||r.reply.contains("\\u"))throw new IllegalArgumentException("Condición o respuesta fuera de los límites del editor.");}
 JSONObject json()throws Exception{JSONArray all=new JSONArray();for(Rule r:rules)all.put(new JSONObject().put("variable",r.variable).put("operation",r.operation).put("trigger",r.trigger).put("reply",r.reply));return new JSONObject().put("replace",replace).put("rules",all);}
 static JavaTextPlan read(String raw)throws Exception{JSONObject j=new JSONObject(raw);if(j.length()!=2)throw new IllegalArgumentException("Campos desconocidos en el plan.");JavaTextPlan p=new JavaTextPlan();p.replace=j.getBoolean("replace");JSONArray list=j.getJSONArray("rules");if(list.length()>12)throw new IllegalArgumentException("Hasta doce condiciones por método.");for(int i=0;i<list.length();i++){JSONObject x=list.getJSONObject(i);if(x.length()!=4)throw new IllegalArgumentException("Regla desconocida.");Rule r=new Rule(x.getString("variable"),x.getString("operation"),x.getString("trigger"),x.getString("reply"));check(r);p.rules.add(r);}return p;}
 static JavaTextPlan raw(String raw)throws Exception{if(raw.length()>6000)throw new IllegalArgumentException("Método demasiado largo.");JavaTextPlan p=new JavaTextPlan();p.replace=true;String body=raw.trim();Pattern rule=Pattern.compile("^if\\s*\\(\\s*(message|text)\\.(equals|startsWith|endsWith|contains)\\(\\s*("+LIT+")\\s*\\)\\s*\\)\\s*return\\s+("+LIT+")\\s*;\\s*");while(!body.equals("return null;")){Matcher m=rule.matcher(body);if(!m.find()||p.rules.size()>=12)throw new IllegalArgumentException("Admito if de equals/startsWith/endsWith/contains con texto literal, respuestas literales y return null; final. No APIs, bucles ni Java general.");Rule r=new Rule(m.group(1),m.group(2),decode(m.group(3)),decode(m.group(4)));check(r);p.rules.add(r);body=body.substring(m.end()).trim();}return p;}
 void add(String operation,String trigger,String reply){Rule r=new Rule("text",operation,ChatLanguage.normalize(trigger).replaceFirst("^banana ",""),reply);check(r);for(int i=rules.size()-1;i>=0;i--){Rule old=rules.get(i);if(old.variable.equals(r.variable)&&old.operation.equals(operation)&&old.trigger.equals(r.trigger))rules.remove(i);}if(rules.size()>=12)throw new IllegalArgumentException("El método admite doce condiciones; reescribilo para reorganizarlas.");rules.add(0,r);}
 String statements(){StringBuilder out=new StringBuilder();for(Rule r:rules)out.append("  if (").append(r.variable).append('.').append(r.operation).append('(').append(literal(r.trigger)).append(")) return ").append(literal(r.reply)).append(";\n");if(replace)out.append("  return null;\n");return out.toString();}
 String expected(String message){String text=ChatLanguage.normalize(message).replaceFirst("^banana ","");for(Rule r:rules){String input=r.variable.equals("text")?text:message;boolean match=r.operation.equals("equals")?input.equals(r.trigger):r.operation.equals("startsWith")?input.startsWith(r.trigger):r.operation.equals("endsWith")?input.endsWith(r.trigger):input.contains(r.trigger);if(match)return r.reply;}return replace?null:ChatLanguage.socialReplyBase(message);}
 static int[] span(String source){String signature="static String socialReply(String message){";int start=source.indexOf(signature);if(start<0)throw new IllegalArgumentException("No encontré la firma socialReply esperada.");int open=start+signature.length()-1;int level=1;boolean quoted=false,escape=false;for(int i=open+1;i<source.length();i++){char ch=source.charAt(i);if(quoted){if(escape)escape=false;else if(ch=='\\')escape=true;else if(ch=='\"')quoted=false;}else if(ch=='\"')quoted=true;else if(ch=='{')level++;else if(ch=='}'&&--level==0)return new int[]{open+1,i};}throw new IllegalArgumentException("El método base no está completo.");}
 String edited(String base){int[] span=span(base);String original=base.substring(span[0],span[1]);String pre="\n  String text=normalize(message).replaceFirst(\"^banana \",\"\");\n";String body=replace?pre+statements():original.replace("  String text=normalize(message).replaceFirst(\"^banana \",\"\");", "  String text=normalize(message).replaceFirst(\"^banana \",\"\");\n"+statements());if(!replace&&body.equals(original)&&!rules.isEmpty())throw new IllegalArgumentException("El método base cambió; no apliqué el parche.");return base.substring(0,span[0])+body+base.substring(span[1]);}
 String compiled(String base){return edited(base).replace("package com.bananalab.lite;","package com.bananalab.patch;").replace("final class ChatLanguage{","public final class ChatLanguagePatched{").replace("static String socialReply(","public static String socialReply(").replace("Knowledge.normalize(text)","java.text.Normalizer.normalize(text.toLowerCase(java.util.Locale.ROOT),java.text.Normalizer.Form.NFD).replaceAll(\"\\\\p{M}\",\"\")");}
 String[] samples(){LinkedHashSet<String> all=new LinkedHashSet<>(Arrays.asList("hola","hola banana","muchas gracias","chau","quiero charlar","un mensaje sin coincidencia","crea una banana","agrega un zorro","publica el borrador","descarta el borrador","aplica la funcion del salto","aplica los cambios de la app","versiones de la app","deshacer","reconstrui la app"));for(Rule r:rules){all.add(r.trigger);all.add(r.trigger+" extra");all.add("extra "+r.trigger);all.add(r.trigger.toUpperCase(java.util.Locale.ROOT));}return all.toArray(new String[0]);}
 void controls(){for(String q:new String[]{"crea una banana","agrega un zorro","publica el borrador","descarta el borrador","aplica la funcion del salto","aplica los cambios de la app","versiones de la app","deshacer","reconstrui la app"})if(expected(q)!=null)throw new IllegalArgumentException("La condición intercepta un control o una orden de creación: "+q);}
}
